  'val.vs_usual_commute': { en: 'vs usual commute', hi: 'सामान्य आवागमन की तुलना में', bn: 'স্বাভাবিক যাতায়াতের তুলনায়', ta: 'வழக்கமான பயணத்துடன் ஒப்பிடும்போது' },
